SPECIALIST_PROMPTS: dict[str, str] = {
    "orders": "You are Rafeeq's Orders specialist. Order lookup, status, "
              "details ONLY. Money or routing? Say out of scope.",
    "logistics": "You are Rafeeq's Logistics specialist. Tracking, ETAs, "
                 "rescheduling ONLY. Never issue refunds.",
    "billing": "You are Rafeeq's Billing specialist. Invoices and refunds "
               "within policy ONLY. Never sees shipment PII.",
}

def make_specialist(name: str, system: str, tools: list[Any]) -> Any:
    """Narrow toolset + single-domain prompt. name = routing target (M6)."""
    return create_react_agent(
        model=get_model_for_specialist().bind_tools(tools),
        tools=tools,
        prompt=SystemMessage(content=system),
        name=name,
    )

# src/rafeeq/agents/scoping.py
SCOPE: dict[str, frozenset[str]] = {
    "orders":    {"customer_id", "locale", "order_id", "messages"},
    "logistics": {"customer_id", "locale", "order_id", "messages"},
    "billing":   {"customer_id", "locale", "order_id", "messages"},  # no address/geo
}

FORBIDDEN_FIELDS = {
    "billing": {"address", "shipment_address", "delivery_address", "geo", "lat", "lng"},
}

def scoped_input(state: Mapping[str, Any], specialist: str) -> dict[str, Any]:
    """Project shared state down to the fields `specialist` may read.
    Structural isolation, not a prompt instruction."""
    allowed = SCOPE[specialist]
    payload = {k: v for k, v in state.items() if k in allowed}
    assert_no_forbidden_leak(payload, specialist)   # raises, never silently passes
    return payload

# src/rafeeq/orchestration/supervisor.py
MAX_HANDOFFS = 4   # GLOBAL budget across ALL agents, imported from core.config

class Route(BaseModel):
    target: Literal["orders", "logistics", "billing", "finish", "escalate"]
    subgoal: str                                  # explicit sub-goal for the handoff

def supervise(state: RafeeqState) -> dict:
    """Decide the next specialist, or finish, or escalate. NO domain work."""
    if state["handoff_count"] >= MAX_HANDOFFS:    # budget -> escalate, never loop
        return {"route": "escalate"}
    router = get_model().with_structured_output(Route)
    decision = router.invoke([SystemMessage(content=ROUTER_SYSTEM_TEXT),
                               *state["messages"]])
    return {"route": decision.target, "subgoal": decision.subgoal}

def route(state: RafeeqState) -> str:
    return state["route"]      # 'orders'|'logistics'|'billing'|'finish'|'escalate'

# src/rafeeq/orchestration/finish.py
def aggregate(state: dict) -> dict:
    """ONE coherent reply from possibly several specialists' results."""
    summary = get_model().invoke([
        SystemMessage(content="Compose ONE clear reply to the customer in "
                              "their language from these specialist results."),
        *state["messages"]])
    return {"messages": [summary], "resolution": "resolved"}

def escalate(state: dict) -> dict:
    """Hand to a human WITH the full trace and state -- never a dead end."""
    _log_escalation(state["ticket_id"], state)        # full context to the human queue
    msg = (ESCALATE_MESSAGE_EN if state["locale"] == "en" else ESCALATE_MESSAGE_AR)
    return {"messages": [AIMessage(content=msg)], "resolution": "escalated"}
